* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

.splash-container {
    min-height: 100vh;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
    position: relative;
    overflow: hidden;
}

.splash-container::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 60%;
    height: 100%;
    background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    clip-path: ellipse(80% 100% at 0% 50%);
    z-index: 1;
}

.splash-content {
    display: flex;
    max-width: 1200px;
    width: 100%;
    height: 600px;
    background: rgba(255, 255, 255, 0.95);
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
    overflow: hidden;
    position: relative;
    z-index: 2;
}

.splash-left {
    flex: 1.2;
    padding: 3rem;
    background: rgba(0, 0, 0, 0.8);
    color: white;
    display: flex;
    flex-direction: column;
    justify-content: center;
    position: relative;
}

.splash-left::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
    background-size: cover;
    background-position: center;
    opacity: 0.3;
    z-index: -1;
}

.branding {
    position: relative;
    z-index: 1;
}

.logo {
    display: flex;
    align-items: center;
    margin-bottom: 2rem;
}

.logo-icon {
    margin-right: 1rem;
}

.site-title {
    font-family: 'Inter', sans-serif;
    font-size: 2.5rem;
    font-weight: 700;
    color: white;
    margin: 0;
}

.tagline {
    font-family: 'Inter', sans-serif;
    font-size: 1.8rem;
    font-weight: 500;
    color: #6c7bf7;
    margin-bottom: 1.5rem;
    line-height: 1.3;
}

.description {
    font-family: 'Inter', sans-serif;
    font-size: 1rem;
    line-height: 1.6;
    color: rgba(255, 255, 255, 0.9);
    margin-bottom: 2rem;
}

.features-list {
    list-style: none;
    padding: 0;
}

.features-list li {
    font-family: 'Inter', sans-serif;
    font-size: 0.95rem;
    color: rgba(255, 255, 255, 0.85);
    margin-bottom: 0.75rem;
    padding-left: 1.5rem;
    position: relative;
}

.features-list li::before {
    content: '•';
    color: #6c7bf7;
    font-size: 1.2rem;
    position: absolute;
    left: 0;
    top: 0;
}

.splash-right {
    flex: 1;
    background: white;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
}

.form-container {
    width: 100%;
    max-width: 400px;
}

/* Responsive Design */
@media (max-width: 968px) {
    .splash-content {
        flex-direction: column;
        height: auto;
        max-height: 90vh;
        overflow-y: auto;
    }
    
    .splash-container::before {
        width: 100%;
        height: 50%;
        clip-path: ellipse(100% 80% at 50% 0%);
    }
    
    .splash-left {
        flex: none;
        padding: 2rem;
        text-align: center;
    }
    
    .site-title {
        font-size: 2rem;
    }
    
    .tagline {
        font-size: 1.4rem;
    }
    
    .features-list {
        text-align: left;
        display: inline-block;
    }
}

@media (max-width: 640px) {
    .splash-container {
        padding: 1rem;
    }
    
    .splash-left {
        padding: 1.5rem;
    }
    
    .splash-right {
        padding: 1.5rem;
    }
    
    .site-title {
        font-size: 1.8rem;
    }
    
    .tagline {
        font-size: 1.2rem;
    }
