.profile-card {
    background: white;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    padding: 2rem;
    font-family: 'Inter', sans-serif;
}

.profile-header {
    display: flex;
    align-items: flex-start;
    gap: 2rem;
    margin-bottom: 2rem;
    flex-wrap: wrap;
}

.profile-avatar {
    flex-shrink: 0;
}

.avatar-placeholder {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: 600;
    font-size: 2.5rem;
    border: 4px solid white;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
}

.profile-info {
    flex: 1;
    min-width: 0;
}

.profile-name {
    font-size: 2rem;
    font-weight: 700;
    color: #1a1a1a;
    margin: 0 0 0.5rem 0;
}

.profile-username {
    font-size: 1.1rem;
    color: #667eea;
    margin: 0 0 1rem 0;
    font-weight: 500;
}

.profile-bio {
    font-size: 1rem;
    color: #555;
    line-height: 1.6;
    margin: 0;
}

.edit-profile-btn {
    background: rgba(102, 126, 234, 0.1);
    color: #667eea;
    border: 1px solid rgba(102, 126, 234, 0.2);
    padding: 0.75rem 1.5rem;
    border-radius: 8px;
    font-family: 'Inter', sans-serif;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    height: fit-content;
}

.edit-profile-btn:hover {
    background: rgba(102, 126, 234, 0.15);
    border-color: rgba(102, 126, 234, 0.3);
    transform: translateY(-1px);
}

.profile-details {
    display: grid;
    gap: 2rem;
}

.profile-stats {
    display: flex;
    gap: 3rem;
    padding: 1.5rem;
    background: rgba(102, 126, 234, 0.05);
    border-radius: 8px;
    border: 1px solid rgba(102, 126, 234, 0.1);
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
}

.stat-number {
    font-size: 1.8rem;
    font-weight: 700;
    color: #667eea;
    margin-bottom: 0.25rem;
}

.stat-label {
    font-size: 0.9rem;
    color: #666;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.profile-meta {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 1rem;
}

.meta-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    color: #666;
    font-size: 0.95rem;
}

.meta-item svg {
    color: #667eea;
    flex-shrink: 0;
}

.profile-link {
    color: #667eea;
    text-decoration: none;
    transition: color 0.2s ease;
}

.profile-link:hover {
    color: #764ba2;
    text-decoration: underline;
}

/* Responsive */
@media (max-width: 768px) {
    .profile-card {
        padding: 1.5rem;
    }
    
    .profile-header {
        flex-direction: column;
        text-align: center;
        gap: 1.5rem;
    }
    
    .avatar-placeholder {
        width: 100px;
        height: 100px;
        font-size: 2rem;
        margin: 0 auto;
    }
    
    .profile-name {
        font-size: 1.5rem;
    }
    
    .profile-stats {
        gap: 2rem;
        justify-content: center;
    }
    
    .profile-meta {
        grid-template-columns: 1fr;
        gap: 0.75rem;
    }
}

@media (max-width: 480px) {
    .profile-card {
        padding: 1rem;
    }
    
    .profile-stats {
        flex-direction: column;
        gap: 1rem;
        text-align: center;
    }
    
    .stat-item {
        flex-direction: row;
        justify-content: space-between;
    }
    
    .stat-number {
        font-size: 1.5rem;
        margin-bottom: 0;
    }
}

.profile-actions {
    display: flex;
    gap: 10px;
    margin-left: auto;
    flex-direction: column;
    align-items: flex-end;
}

.edit-profile-btn {
    background-color: #007bff;
    color: white;
    border: none;
    padding: 8px 16px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    transition: background-color 0.2s;
}

.edit-profile-btn:hover {
    background-color: #0056b3;
}

.delete-profile-btn {
    background-color: #dc3545;
    color: white;
    border: none;
    padding: 8px 16px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    transition: background-color 0.2s;
    margin-top: 8px;
}

.delete-profile-btn:hover {
    background-color: #c82333;
}

.add-friend-profile-btn {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    padding: 8px 16px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    transition: all 0.2s;
    font-weight: 500;
}

.add-friend-profile-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
}

.add-friend-profile-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    transform: none;
}

.unfriend-profile-btn {
    background-color: rgba(239, 68, 68, 0.1);
    color: #ef4444;
    border: 1px solid rgba(239, 68, 68, 0.2);
    padding: 8px 16px;
    border-radius: 6px;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    transition: all 0.2s;
    font-weight: 500;
}

.unfriend-profile-btn:hover {
    background-color: rgba(239, 68, 68, 0.15);
    border-color: rgba(239, 68, 68, 0.3);
}

.unfriend-profile-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

/* Ensure the profile header layout works well with the buttons */
.profile-header {
    display: flex;
    align-items: flex-start;
    gap: 20px;
    position: relative;
}

.profile-info {
    flex: 1;
}

@media (max-width: 768px) {
    .profile-actions {
        flex-direction: row;
        margin-left: 0;
        margin-top: 15px;
        width: 100%;
        justify-content: flex-start;
    }
    
    .delete-profile-btn {
        margin-top: 0;
    }
