.search-form {
    position: relative;
    display: flex;
    align-items: center;
}

.search-input {
    font-family: 'Inter', sans-serif;
    width: 200px;
    padding: 0.5rem 2.5rem 0.5rem 1rem;
    border: 1.5px solid #e1e5e9;
    border-radius: 20px;
    font-size: 0.9rem;
    background: #f8f9fa;
    transition: all 0.2s ease;
}

.search-input:focus {
    outline: none;
    border-color: #667eea;
    background: white;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
    width: 250px;
}

.search-input::placeholder {
    color: #999;
}

.search-btn {
    position: absolute;
    right: 0.5rem;
    background: none;
    border: none;
    color: #666;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.search-btn:hover {
    color: #667eea;
    background: rgba(102, 126, 234, 0.1);
}

/* Responsive */
@media (max-width: 768px) {
    .search-input {
        width: 150px;
    }
    
    .search-input:focus {
        width: 180px;
    }
