___CSS_LOADER_EXPORT___.push([module.id, `.projects-page {
    min-height: 100vh;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.projects-container {
    max-width: 1400px;
    margin: 0 auto;
    padding: 2rem;
}

.projects-header {
    text-align: center;
    color: white;
    margin-bottom: 2rem;
}

.projects-header h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
    font-weight: 700;
}

.projects-header p {
    font-size: 1.1rem;
    opacity: 0.9;
}

/* Collaboration Controls */
.collaboration-controls {
    background: #f8f9fa;
    padding: 20px;
    border-radius: 8px;
    margin-bottom: 20px;
    border-left: 4px solid #007bff;
}

.project-status {
    margin-bottom: 15px;
    font-size: 16px;
}

.status-badge {
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 14px;
    font-weight: bold;
    margin: 0 10px;
}

.status-badge.checked-in {
    background: #28a745;
    color: white;
}

.status-badge.checked-out {
    background: #dc3545;
    color: white;
}

.checked-out-by {
    color: #666;
    font-style: italic;
}

.collaboration-buttons {
    display: flex;
    gap: 10px;
    align-items: center;
}

.btn-checkout {
    background: #007bff;
    color: white;
    border: none;
    padding: 10px 20px;
    border-radius: 4px;
    cursor: pointer;
}

.btn-checkout:hover:not(:disabled) {
    background: #0056b3;
}

.btn-checkout:disabled {
    background: #6c757d;
    cursor: not-allowed;
}

.btn-checkin {
    background: #28a745;
    color: white;
    border: none;
    padding: 10px 20px;
    border-radius: 4px;
    cursor: pointer;
}

.btn-checkin:hover {
    background: #218838;
}

.checkout-warning {
    color: #856404;
    background: #fff3cd;
    padding: 10px;
    border-radius: 4px;
    border: 1px solid #ffeaa7;
}

/* Checkin Form */
.checkin-form {
    background: white;
    padding: 20px;
    border-radius: 8px;
    margin-bottom: 20px;
    border: 1px solid #dee2e6;
}

.checkin-form h3 {
    margin-bottom: 20px;
    color: #333;
}

.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 5px;
    font-weight: bold;
    color: #333;
}

.form-group textarea,
.form-group input[type="text"],
.form-group input[type="file"] {
    width: 100%;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 14px;
}

.form-group textarea {
    resize: vertical;
    min-height: 80px;
}

.file-preview {
    margin-top: 10px;
}

.file-preview h4 {
    margin-bottom: 10px;
    color: #333;
}

.file-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px;
    background: #f8f9fa;
    border-radius: 4px;
    margin-bottom: 5px;
}

.file-item button {
    background: #dc3545;
    color: white;
    border: none;
    padding: 4px 8px;
    border-radius: 3px;
    cursor: pointer;
    font-size: 12px;
}

.form-actions {
    display: flex;
    gap: 10px;
}

.btn-primary {
    background: #007bff;
    color: white;
    border: none;
    padding: 10px 20px;
    border-radius: 4px;
    cursor: pointer;
}

.btn-primary:hover:not(:disabled) {
    background: #0056b3;
}

.btn-primary:disabled {
    background: #6c757d;
    cursor: not-allowed;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border: none;
    padding: 10px 20px;
    border-radius: 4px;
    cursor: pointer;
}

.btn-secondary:hover {
    background: #545b62;
