.edit-project-card {
    background: white;
    border-radius: 12px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    padding: 2rem;
    font-family: 'Inter', sans-serif;
}

.edit-project-header {
    margin-bottom: 2rem;
}

.edit-project-title {
    font-size: 1.5rem;
    font-weight: 600;
    color: #1a1a1a;
    margin: 0 0 0.5rem 0;
}

.edit-project-subtitle {
    color: #666;
    margin: 0;
    font-size: 0.95rem;
}

.edit-project-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-group {
    flex: 1;
}

.form-group label {
    display: block;
    font-weight: 500;
    color: #333;
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
}

.form-group input,
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.875rem 1rem;
    border: 1.5px solid #e1e5e9;
    border-radius: 8px;
    font-size: 0.95rem;
    font-family: 'Inter', sans-serif;
    transition: all 0.2s ease;
    background: #fafbfc;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #667eea;
    background: white;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

.form-group input.error,
.form-group textarea.error,
.form-group select.error {
    border-color: #e74c3c;
    background: #fdf2f2;
}

.form-group input.error:focus,
.form-group textarea.error:focus,
.form-group select.error:focus {
    box-shadow: 0 0 0 3px rgba(231, 76, 60, 0.1);
}

.form-group textarea {
    resize: vertical;
    min-height: 100px;
}

.form-group select {
    cursor: pointer;
}

.error-message {
    display: block;
    color: #e74c3c;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    font-weight: 500;
}

.char-count,
.input-help {
    display: block;
    text-align: right;
    color: #999;
    font-size: 0.8rem;
    margin-top: 0.25rem;
}

.input-help {
    text-align: left;
}

.current-image-section {
    margin: 1rem 0;
}

.current-image-label {
    display: block;
    font-weight: 500;
    color: #333;
    margin-bottom: 0.5rem;
    font-size: 0.9rem;
}

.current-image-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1rem;
    border: 1px solid #e1e5e9;
    border-radius: 8px;
    background: #f8f9fa;
}

.image-placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    color: #667eea;
    text-align: center;
}

.image-placeholder span {
    font-size: 0.85rem;
    font-weight: 500;
}

.change-image-btn {
    background: rgba(102, 126, 234, 0.1);
    color: #667eea;
    border: 1px solid rgba(102, 126, 234, 0.2);
    padding: 0.5rem 1rem;
    border-radius: 6px;
    font-family: 'Inter', sans-serif;
    font-weight: 500;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s ease;
}

.change-image-btn:hover {
    background: rgba(102, 126, 234, 0.15);
    transform: translateY(-1px);
}

.form-actions {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 2rem;
    padding-top: 2rem;
    border-top: 1px solid #e1e5e9;
    gap: 1rem;
}

.form-actions-left,
.form-actions-right {
    display: flex;
    gap: 1rem;
}

.delete-btn,
.cancel-btn,
.save-btn {
    padding: 0.75rem 2rem;
    border-radius: 8px;
    font-family: 'Inter', sans-serif;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 0.95rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.delete-btn {
    background: rgba(239, 68, 68, 0.1);
    color: #dc2626;
    border: 1.5px solid rgba(239, 68, 68, 0.2);
}

.delete-btn:hover {
    background: rgba(239, 68, 68, 0.15);
    border-color: rgba(239, 68, 68, 0.3);
    transform: translateY(-1px);
}

.cancel-btn {
    background: white;
    color: #666;
    border: 1.5px solid #e1e5e9;
}

.cancel-btn:hover {
    border-color: #667eea;
    color: #667eea;
    background: rgba(102, 126, 234, 0.05);
}

.save-btn {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
}

.save-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 25px rgba(102, 126, 234, 0.3);
}

.save-btn:active {
    transform: translateY(0);
}

/* Responsive */
@media (max-width: 768px) {
    .edit-project-card {
        padding: 1.5rem;
    }
    
    .form-row {
        flex-direction: column;
        gap: 0;
    }
    
    .form-row .form-group {
        margin-bottom: 1.5rem;
    }
    
    .current-image-preview {
        flex-direction: column;
        text-align: center;
        gap: 1rem;
    }
    
    .form-actions {
        flex-direction: column;
        gap: 1rem;
        align-items: stretch;
    }
    
    .form-actions-left,
    .form-actions-right {
        width: 100%;
        justify-content: center;
    }
    
    .form-actions-right {
        flex-direction: column;
        gap: 0.75rem;
    }
    
    .delete-btn,
    .cancel-btn,
    .save-btn {
        width: 100%;
        justify-content: center;
    }
}

@media (max-width: 480px) {
    .edit-project-card {
        padding: 1rem;
    }
    
    .form-group input,
    .form-group textarea,
    .form-group select {
        padding: 0.75rem;
    }
    
    .current-image-preview {
        padding: 0.75rem;
    }
    
    .form-actions-left {
        order: 2;
    }
    
    .form-actions-right {
        order: 1;
    }
